// ── Recursive-descent parser for arithmetic expressions ─────────
//
// Grammar (unambiguous, right-recursive for LL parsing):
//   E → T { ('+' | '-') T }
//   T → F { ('*' | '/') F }
//   F → '(' E ')' | NUMBER
//
// Each non-terminal becomes a function. Operator precedence falls
// out naturally from the grammar's level structure — no precedence
// table needed. This grammar is LL(1): one token of lookahead.

function tokenise(src) {
  return src.replace(/([+\-*/()])/g, ' $1 ').trim().split(/\s+/);
}

function parseExpr(tokens, pos = { i: 0 }) {
  // E → T { ('+' | '-') T }
  let left = parseTerm(tokens, pos);
  while (tokens[pos.i] === '+' || tokens[pos.i] === '-') {
    const op = tokens[pos.i++];
    const right = parseTerm(tokens, pos);
    left = { op, left, right };   // build AST node
  }
  return left;
}

function parseTerm(tokens, pos) {
  // T → F { ('*' | '/') F }
  let left = parseFactor(tokens, pos);
  while (tokens[pos.i] === '*' || tokens[pos.i] === '/') {
    const op = tokens[pos.i++];
    const right = parseFactor(tokens, pos);
    left = { op, left, right };
  }
  return left;
}

function parseFactor(tokens, pos) {
  // F → '(' E ')' | NUMBER
  if (tokens[pos.i] === '(') {
    pos.i++;                        // consume '('
    const node = parseExpr(tokens, pos);
    if (tokens[pos.i] !== ')') throw new Error('Expected )');
    pos.i++;                        // consume ')'
    return node;
  }
  const n = Number(tokens[pos.i++]);
  if (isNaN(n)) throw new Error(`Unexpected token: ${tokens[pos.i - 1]}`);
  return { num: n };
}

function evaluate(node) {
  if ('num' in node) return node.num;
  const l = evaluate(node.left);
  const r = evaluate(node.right);
  switch (node.op) {
    case '+': return l + r;
    case '-': return l - r;
    case '*': return l * r;
    case '/': return l / r;
  }
}

// Test cases that verify precedence and associativity
const tests = [
  ['3 + 4 * 2',       11],  // * binds tighter: 3 + (4*2)
  ['(3 + 4) * 2',     14],  // parens override precedence
  ['10 - 3 - 2',       5],  // left-associative: (10-3)-2
  ['2 * (3 + 4 * 1)', 14],  // nested: 3+4=7, 7*2=14
];

for (const [expr, expected] of tests) {
  const tokens = tokenise(expr);
  const ast    = parseExpr(tokens);
  const result = evaluate(ast);
  console.log(`${expr} = ${result} ${result === expected ? 'PASS' : 'FAIL (expected ' + expected + ')'}`);
}

// ── PDA simulation: balanced multi-bracket checker ──────────────
//
// This is a manual simulation of a PDA with stack alphabet {(,[,{}
// The grammar it recognises:
//   S → ( S ) | [ S ] | { S } | S S | ε
// which is a CFG for balanced mixed brackets.

function isBalanced(input) {
  const stack = [];   // the PDA stack
  const open  = '([{';
  const close = ')]}';
  const match = { ')': '(', ']': '[', '}': '{' };

  for (const ch of input) {
    if (open.includes(ch)) {
      stack.push(ch);          // PDA: push state
    } else if (close.includes(ch)) {
      if (stack.length === 0) return false;   // stack underflow
      if (stack.pop() !== match[ch]) return false; // mismatch
    }
    // non-bracket characters ignored (terminals not in Σ_bracket)
  }
  return stack.length === 0;  // accept iff stack empty
}

// Test cases
console.log(isBalanced('({[]})'));   // true
console.log(isBalanced('([)]'));     // false — wrong nesting
console.log(isBalanced('{[}'));      // false — premature close
console.log(isBalanced('((()))'));   // true
console.log(isBalanced(''));         // true — ε is in the language

// ── Grammar ambiguity demonstration ─────────────────────────────
//
// Ambiguous: E → E + E | E * E | number
// Two parse trees for '1 + 2 * 3':
//   Tree A (wrong): ( (1+2) * 3 ) = 9
//   Tree B (right): ( 1 + (2*3) ) = 7
//
// Unambiguous fix: E → E + T | T,  T → T * F | F,  F → number
// The layered grammar forces * to bind tighter than + structurally.
//
// This is why every language grammar specification uses separate
// productions for each precedence level.

function showAmbiguity() {
  // Ambiguous evaluation order
  const treeA = (1 + 2) * 3;  // = 9
  const treeB = 1 + (2 * 3);  // = 7
  console.log('Tree A (wrong precedence):', treeA);
  console.log('Tree B (correct):         ', treeB);
  // Correct parser should always produce treeB = 7
}
showAmbiguity();
